def _is_valid_invoice(invoice: dict, accepted_statuses: set) -> bool:
    """Return True if the invoice passes all inclusion criteria."""
    region = invoice.get("region")
    status = invoice.get("status")
    amount_cents = invoice.get("amount_cents")
    return (
        status in accepted_statuses
        and isinstance(region, str)
        and region != ""
        and isinstance(amount_cents, int)
    )


def _accumulate_totals(invoices: list[dict], accepted_statuses: set) -> dict[str, dict]:
    """Build a mapping of region -> {item_count, cents_total}."""
    totals: dict[str, dict] = {}
    for invoice in invoices:
        if not _is_valid_invoice(invoice, accepted_statuses):
            continue
        region = invoice["region"]
        amount_cents = invoice["amount_cents"]
        if region not in totals:
            totals[region] = {"item_count": 0, "cents_total": 0}
        totals[region]["item_count"] += 1
        totals[region]["cents_total"] += amount_cents
    return totals


def _build_result(totals: dict[str, dict]) -> list[dict]:
    """Convert the totals mapping into a sorted list of summary dicts."""
    return [
        {
            "bucket_code": region,
            "item_count": data["item_count"],
            "cents_total": data["cents_total"],
        }
        for region, data in sorted(totals.items())
    ]


def summarize_invoices(invoices: list[dict], *, include_unpaid: bool = False) -> list[dict]:
    """
    Summarize paid (and optionally unpaid) invoices grouped by region.

    Args:
        invoices: List of invoice dictionaries.
        include_unpaid: When True, include invoices with status "unpaid" in
                        addition to "paid". Defaults to False.

    Returns:
        List of summary dictionaries sorted by region with keys:
        'bucket_code', 'item_count', 'cents_total'.

    Raises:
        TypeError: If invoices is not a list, any element is not a dict,
                   or include_unpaid is not a bool.
    """
    if not isinstance(invoices, list):
        raise TypeError(
            f"invoices must be a list, got {type(invoices).__name__}"
        )
    for index, item in enumerate(invoices):
        if not isinstance(item, dict):
            raise TypeError(
                f"Each invoice must be a dict; item at index {index} is "
                f"{type(item).__name__}"
            )
    if not isinstance(include_unpaid, bool):
        raise TypeError(
            f"include_unpaid must be a bool, got {type(include_unpaid).__name__}"
        )

    accepted_statuses = {"paid", "unpaid"} if include_unpaid else {"paid"}
    totals = _accumulate_totals(invoices, accepted_statuses)
    return _build_result(totals)
