def build_sessions(events: list[dict], gap_seconds: int) -> list[dict]:
    valid = sorted(_valid_events(events), key=lambda item: (item["user_id"], item["timestamp"]))
    sessions = []
    current = None
    for event in valid:
        current, session = _process_event(current, event, gap_seconds)
        if session is not None:
            sessions.append(session)
    if current is not None:
        sessions.append(_finalize(current))
    return sessions


def _process_event(current: dict | None, event: dict, gap_seconds: int):
    if current is None or _starts_new_session(current, event, gap_seconds):
        session = _finalize(current) if current is not None else None
        new_current = {
            "user_id": event["user_id"],
            "start": event["timestamp"],
            "end": event["timestamp"],
            "count": 1,
        }
        return new_current, session
    else:
        current["end"] = event["timestamp"]
        current["count"] += 1
